package com.example.json;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

public class User {

    private long id;
    private String name;
    private String email;
    private List<String> roles;
    private Instant createdAt;

    public User() {
    }

    public User(long id, String name, String email, List<String> roles, Instant createdAt) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.roles = roles;
        this.createdAt = createdAt;
    }

    public long getId() {
        return id;
    }

    public void setId(long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public List<String> getRoles() {
        return roles;
    }

    public void setRoles(List<String> roles) {
        this.roles = roles;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof User)) {
            return false;
        }
        User user = (User) o;
        return id == user.id
                && Objects.equals(name, user.name)
                && Objects.equals(email, user.email)
                && Objects.equals(roles, user.roles)
                && Objects.equals(createdAt, user.createdAt);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, name, email, roles, createdAt);
    }

    @Override
    public String toString() {
        return "User{id=" + id + ", name='" + name + "', email='" + email
                + "', roles=" + roles + ", createdAt=" + createdAt + '}';
    }
}

package com.example.json;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.util.List;

/**
 * Thin wrapper around Jackson's {@link ObjectMapper} for reading and writing JSON.
 */
public final class JsonUtils {

    private static final ObjectMapper MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

    private JsonUtils() {
    }

    public static ObjectMapper mapper() {
        return MAPPER;
    }

    /** Serialize any object to a pretty-printed JSON string. */
    public static String toJson(Object value) {
        try {
            return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(value);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Failed to serialize object to JSON", e);
        }
    }

    /** Parse a JSON string into the given type. */
    public static <T> T fromJson(String json, Class<T> type) {
        try {
            return MAPPER.readValue(json, type);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Failed to parse JSON into " + type.getName(), e);
        }
    }

    /** Parse a JSON array string into a list of the given element type. */
    public static <T> List<T> fromJsonList(String json, Class<T> elementType) {
        try {
            return MAPPER.readValue(json, MAPPER.getTypeFactory()
                    .constructCollectionType(List.class, elementType));
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Failed to parse JSON array into List<"
                    + elementType.getName() + ">", e);
        }
    }

    /** Parse a JSON string using a full generic type reference, e.g. {@code Map<String, User>}. */
    public static <T> T fromJson(String json, TypeReference<T> type) {
        try {
            return MAPPER.readValue(json, type);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Failed to parse JSON", e);
        }
    }
}

package com.example.json;

import java.time.Instant;
import java.util.List;

public final class App {

    private App() {
    }

    public static void main(String[] args) {
        User user = new User(
                42L,
                "Ada Lovelace",
                "ada@example.com",
                List.of("admin", "developer"),
                Instant.parse("2026-01-15T09:30:00Z"));

        String json = JsonUtils.toJson(user);
        System.out.println("Generated JSON:");
        System.out.println(json);

        User parsed = JsonUtils.fromJson(json, User.class);
        System.out.println("Parsed back: " + parsed);
        System.out.println("Round-trip equal: " + user.equals(parsed));
    }
}

package com.example.json;

import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class JsonUtilsTest {

    @Test
    void serializesUserToJson() {
        User user = new User(1L, "Grace Hopper", "grace@example.com",
                List.of("admin"), Instant.parse("2026-02-01T12:00:00Z"));

        String json = JsonUtils.toJson(user);

        assertTrue(json.contains("\"name\" : \"Grace Hopper\""));
        assertTrue(json.contains("\"createdAt\" : \"2026-02-01T12:00:00Z\""));
    }

    @Test
    void parsesUserFromJson() {
        String json = """
                {
                  "id" : 7,
                  "name" : "Alan Turing",
                  "email" : "alan@example.com",
                  "roles" : [ "developer" ],
                  "createdAt" : "2026-03-10T08:15:00Z"
                }
                """;

        User user = JsonUtils.fromJson(json, User.class);

        assertEquals(7L, user.getId());
        assertEquals("Alan Turing", user.getName());
        assertEquals(List.of("developer"), user.getRoles());
        assertEquals(Instant.parse("2026-03-10T08:15:00Z"), user.getCreatedAt());
    }

    @Test
    void roundTripsUser() {
        User user = new User(99L, "Katherine Johnson", "katherine@example.com",
                List.of("analyst", "admin"), Instant.parse("2026-04-05T17:45:00Z"));

        User parsed = JsonUtils.fromJson(JsonUtils.toJson(user), User.class);

        assertEquals(user, parsed);
    }

    @Test
    void parsesJsonArray() {
        String json = """
                [
                  { "id" : 1, "name" : "A", "email" : "a@example.com", "roles" : [], "createdAt" : "2026-01-01T00:00:00Z" },
                  { "id" : 2, "name" : "B", "email" : "b@example.com", "roles" : [ "user" ], "createdAt" : "2026-01-02T00:00:00Z" }
                ]
                """;

        List<User> users = JsonUtils.fromJsonList(json, User.class);

        assertEquals(2, users.size());
        assertEquals("B", users.get(1).getName());
    }
}
